mapper.select:
SELECT 
  FROM TB_USER U
 WHERE U.USER_ID = #{userId}

mapper.update:
UPDATE TB_USER
   SET USER_NM = #{u.userNm}
     , DEPT_CD = #{u.deptCd}
     , EMAIL   = #{u.email,jdbcType=VARCHAR}
     , JOIN_DT = TO_DATE(#{u.joinDt,jdbcType=VARCHAR}, 'YYYY-MM-DD')
     , SALARY  = #{u.salary,jdbcType=NUMERIC}
     , USE_YN  = COALESCE(#{u.useYn,jdbcType=VARCHAR}, 'Y')
     , REMARK  = #{u.remark,jdbcType=VARCHAR}
     , MOD_ID  = #{loginId}
     , MOD_DT  = CURRENT_TIMESTAMP
 WHERE USER_ID = #{u.userId}
